# 7-peygamberimizin-hayati-15 görsel modülü

GORSELLER = {'b1': '<svg viewBox="0 0 760 300" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif"><rect width="760" height="300" fill="#f8fafc" rx="14"/><text x="380" y="32" text-anchor="middle" font-size="16" font-weight="bold" fill="#1e293b">MUHACİRLERİN BAĞLILIĞININ ÜÇ YÖNÜ</text><rect x="30" y="52" width="200" height="135" rx="10" fill="#fef2f2" stroke="#ef4444"/><text x="130" y="76" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">1. Sevgi (Muhabbet)</text><text x="42" y="100" font-size="11" fill="#334155">Onu canından, ailesinden</text><text x="42" y="117" font-size="11" fill="#334155">ve malından çok sevmek</text><text x="42" y="142" font-size="11" fill="#7f1d1d">Hz. Ömer: "Şimdi canımdan</text><text x="42" y="159" font-size="11" fill="#7f1d1d">da sevimlisin!" (Buhârî)</text><line x1="232" y1="120" x2="272" y2="120" stroke="#64748b" stroke-width="2"/><polygon points="272,114 282,120 272,126" fill="#64748b"/><rect x="280" y="52" width="200" height="135" rx="10" fill="#eff6ff" stroke="#3b82f6"/><text x="380" y="76" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">2. Saygı (Ta\'zim)</text><text x="292" y="100" font-size="11" fill="#334155">Huzurunda edepli olmak,</text><text x="292" y="117" font-size="11" fill="#334155">sözünü dikkatle dinlemek</text><text x="292" y="142" font-size="11" fill="#1e3a8a">Urve: "Hiçbir hükümdara</text><text x="292" y="159" font-size="11" fill="#1e3a8a">böyle saygı görmedim."</text><line x1="482" y1="120" x2="522" y2="120" stroke="#64748b" stroke-width="2"/><polygon points="522,114 532,120 522,126" fill="#64748b"/><rect x="530" y="52" width="200" height="135" rx="10" fill="#f0fdf4" stroke="#22c55e"/><text x="630" y="76" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">3. Uyma (İttiba)</text><text x="542" y="100" font-size="11" fill="#334155">Sözünü ve sünnetini</text><text x="542" y="117" font-size="11" fill="#334155">hayata geçirmek</text><text x="542" y="142" font-size="11" fill="#14532d">"Allah\'ı seviyorsanız</text><text x="542" y="159" font-size="11" fill="#14532d">bana uyun." (Âl-i İmrân, 31)</text><rect x="30" y="205" width="700" height="78" rx="10" fill="#fffbeb" stroke="#f59e0b"/><text x="380" y="228" text-anchor="middle" font-size="13" font-weight="bold" fill="#b45309">Ölçülü Sevgi Uyarısı</text><text x="380" y="249" text-anchor="middle" font-size="12" fill="#334155">"Beni aşırı övmeyin; ben ancak bir kulum. Allah\'ın kulu ve Resulü deyin." (Buhârî)</text><text x="380" y="270" text-anchor="middle" font-size="12" fill="#334155">Sevgi; onu yüceltip ilahlaştırmak değil, güzel örnek bilip izinden gitmektir (Ahzâb, 21).</text></svg>', 'b2': '<svg viewBox="0 0 760 310" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif"><rect width="760" height="310" fill="#f8fafc" rx="14"/><text x="380" y="32" text-anchor="middle" font-size="16" font-weight="bold" fill="#1e293b">İKİ MUHACİRİN GÖZÜNDEN PEYGAMBERİMİZ</text><rect x="25" y="50" width="345" height="240" rx="10" fill="#eff6ff" stroke="#3b82f6"/><text x="197" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Hz. Ali\'nin Tasviriyle (Tirmizî)</text><text x="40" y="102" font-size="11" fill="#334155">• Ne aşırı uzun ne de kısa boyluydu.</text><text x="40" y="124" font-size="11" fill="#334155">• İnsanların en cömert gönüllüsü ve</text><text x="40" y="141" font-size="11" fill="#334155">  en doğru sözlüsüydü.</text><text x="40" y="163" font-size="11" fill="#334155">• En yumuşak huylu, en iyi arkadaştı.</text><text x="40" y="185" font-size="11" fill="#334155">• Ansızın gören heybetinden çekinir,</text><text x="40" y="202" font-size="11" fill="#334155">  tanışıp kaynaşan onu severdi.</text><rect x="40" y="222" width="315" height="52" rx="8" fill="#dbeafe"/><text x="197" y="244" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">"Ne ondan önce ne de ondan sonra</text><text x="197" y="262" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">onun gibisini görmedim."</text><rect x="390" y="50" width="345" height="240" rx="10" fill="#fdf4ff" stroke="#c026d3"/><text x="562" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#a21caf">Hz. Aişe\'nin Anlatımıyla Evde</text><text x="405" y="102" font-size="11" fill="#334155">• Ailesinin işlerine yardım ederdi.</text><text x="405" y="119" font-size="11" fill="#334155">  Namaz vakti gelince namaza çıkardı.</text><text x="405" y="141" font-size="11" fill="#334155">• Kötü söz söylemez, bağırıp çağırmazdı.</text><text x="405" y="163" font-size="11" fill="#334155">• Kötülüğe kötülükle karşılık vermez;</text><text x="405" y="180" font-size="11" fill="#334155">  affeder ve bağışlardı. (Tirmizî)</text><text x="405" y="202" font-size="11" fill="#334155">• Günah olmadıkça kolay olanı seçerdi.</text><rect x="405" y="222" width="315" height="52" rx="8" fill="#fae8ff"/><text x="562" y="244" text-anchor="middle" font-size="11" font-weight="bold" fill="#701a75">Sonuç: Toplum içinde nasılsa</text><text x="562" y="262" text-anchor="middle" font-size="11" font-weight="bold" fill="#701a75">evinde de öyleydi: tutarlı ve samimi.</text></svg>', 'b3': '<svg viewBox="0 0 760 320" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif"><rect width="760" height="320" fill="#f8fafc" rx="14"/><text x="380" y="32" text-anchor="middle" font-size="16" font-weight="bold" fill="#1e293b">HANIM MUHACİRLERİN VEFASI</text><rect x="20" y="50" width="230" height="250" rx="12" fill="#ecfeff" stroke="#0891b2"/><text x="135" y="76" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Hz. Ümmü Seleme</text><text x="135" y="94" text-anchor="middle" font-size="10" fill="#155e75">Habeşistan ve Medine muhaciri</text><text x="32" y="122" font-size="11" fill="#334155">• Eşinden ve oğlundan ayrı</text><text x="32" y="139" font-size="11" fill="#334155">  bırakıldı; bir yıla yakın</text><text x="32" y="156" font-size="11" fill="#334155">  sabredip yalnız hicret etti.</text><text x="32" y="182" font-size="11" fill="#334155">• Hudeybiye\'de Peygamberimize</text><text x="32" y="199" font-size="11" fill="#334155">  isabetli görüş sundu.</text><rect x="40" y="250" width="190" height="32" rx="8" fill="#cffafe"/><text x="135" y="271" text-anchor="middle" font-size="12" font-weight="bold" fill="#164e63">Sabır ve Feraset</text><rect x="265" y="50" width="230" height="250" rx="12" fill="#fefce8" stroke="#ca8a04"/><text x="380" y="76" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Hz. Esma bint Ebu Bekir</text><text x="380" y="94" text-anchor="middle" font-size="10" fill="#854d0e">Zâtü\'n-nitâkayn (iki kuşaklı)</text><text x="277" y="122" font-size="11" fill="#334155">• Sevr\'e gizlice azık taşıdı;</text><text x="277" y="139" font-size="11" fill="#334155">  kuşağını ikiye bölüp</text><text x="277" y="156" font-size="11" fill="#334155">  azık torbasını bağladı.</text><text x="277" y="182" font-size="11" fill="#334155">• Müşriklere Peygamberimizin</text><text x="277" y="199" font-size="11" fill="#334155">  yerini söylemedi.</text><text x="277" y="222" font-size="11" fill="#334155">• Âmâ dedesini teselli etti.</text><rect x="285" y="250" width="190" height="32" rx="8" fill="#fef9c3"/><text x="380" y="271" text-anchor="middle" font-size="12" font-weight="bold" fill="#713f12">Cesaret ve Sır Tutma</text><rect x="510" y="50" width="230" height="250" rx="12" fill="#fff1f2" stroke="#e11d48"/><text x="625" y="76" text-anchor="middle" font-size="13" font-weight="bold" fill="#be123c">Hz. Ümmü Eymen</text><text x="625" y="94" text-anchor="middle" font-size="10" fill="#9f1239">Bereke: Peygamberimizin dadısı</text><text x="522" y="122" font-size="11" fill="#334155">• "Annemden sonra annemdir"</text><text x="522" y="139" font-size="11" fill="#334155">  iltifatına mazhar oldu.</text><text x="522" y="165" font-size="11" fill="#334155">• Peygamberimizin vefatından</text><text x="522" y="182" font-size="11" fill="#334155">  sonra vahyin kesilmesine</text><text x="522" y="199" font-size="11" fill="#334155">  ağladı. (Müslim)</text><rect x="530" y="250" width="190" height="32" rx="8" fill="#ffe4e6"/><text x="625" y="271" text-anchor="middle" font-size="12" font-weight="bold" fill="#881337">Şefkat ve Vefa</text></svg>', 'b4': '<svg viewBox="0 0 760 300" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif"><rect width="760" height="300" fill="#f8fafc" rx="14"/><text x="380" y="32" text-anchor="middle" font-size="16" font-weight="bold" fill="#1e293b">ABDULLAH BİN MES\'UD\'UN HAYATINDAN BAĞLILIK DURAKLARI</text><line x1="60" y1="130" x2="700" y2="130" stroke="#94a3b8" stroke-width="4"/><circle cx="90" cy="130" r="14" fill="#6366f1"/><text x="90" y="135" text-anchor="middle" font-size="12" font-weight="bold" fill="#ffffff">1</text><circle cx="235" cy="130" r="14" fill="#6366f1"/><text x="235" y="135" text-anchor="middle" font-size="12" font-weight="bold" fill="#ffffff">2</text><circle cx="380" cy="130" r="14" fill="#6366f1"/><text x="380" y="135" text-anchor="middle" font-size="12" font-weight="bold" fill="#ffffff">3</text><circle cx="525" cy="130" r="14" fill="#6366f1"/><text x="525" y="135" text-anchor="middle" font-size="12" font-weight="bold" fill="#ffffff">4</text><circle cx="670" cy="130" r="14" fill="#6366f1"/><text x="670" y="135" text-anchor="middle" font-size="12" font-weight="bold" fill="#ffffff">5</text><text x="90" y="100" text-anchor="middle" font-size="12" font-weight="bold" fill="#3730a3">İlk Müslümanlardan</text><text x="235" y="100" text-anchor="middle" font-size="12" font-weight="bold" fill="#3730a3">Kâbe\'de Rahman</text><text x="380" y="100" text-anchor="middle" font-size="12" font-weight="bold" fill="#3730a3">İki Hicret</text><text x="525" y="100" text-anchor="middle" font-size="12" font-weight="bold" fill="#3730a3">Yakın Hizmet</text><text x="670" y="100" text-anchor="middle" font-size="12" font-weight="bold" fill="#3730a3">Nisâ 41 Hatırası</text><text x="90" y="168" text-anchor="middle" font-size="11" fill="#334155">Genç ve korumasız</text><text x="90" y="184" text-anchor="middle" font-size="11" fill="#334155">bir çobandı</text><text x="235" y="168" text-anchor="middle" font-size="11" fill="#334155">Açıktan okudu,</text><text x="235" y="184" text-anchor="middle" font-size="11" fill="#334155">dövüldü, yılmadı</text><text x="380" y="168" text-anchor="middle" font-size="11" fill="#334155">Önce Habeşistan,</text><text x="380" y="184" text-anchor="middle" font-size="11" fill="#334155">sonra Medine</text><text x="525" y="168" text-anchor="middle" font-size="11" fill="#334155">Ayakkabı, misvak</text><text x="525" y="184" text-anchor="middle" font-size="11" fill="#334155">ve abdest suyu</text><text x="670" y="168" text-anchor="middle" font-size="11" fill="#334155">"Bana Kur\'an oku"</text><text x="670" y="184" text-anchor="middle" font-size="11" fill="#334155">daveti ve gözyaşı</text><rect x="60" y="215" width="640" height="62" rx="10" fill="#eef2ff" stroke="#6366f1"/><text x="380" y="240" text-anchor="middle" font-size="12" font-weight="bold" fill="#312e81">"Kur\'an\'ı dört kişiden öğrenin: Abdullah bin Mes\'ud, Salim, Muaz ve Übey."</text><text x="380" y="262" text-anchor="middle" font-size="11" fill="#334155">Peygamberimizin saydığı kişilerin ilki İbn Mes\'ud\'dur (Buhârî).</text></svg>', 'b5': '<svg viewBox="0 0 760 320" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif"><rect width="760" height="320" fill="#f8fafc" rx="14"/><text x="380" y="32" text-anchor="middle" font-size="16" font-weight="bold" fill="#1e293b">VEFATTAN SONRA DA SÜREN SADAKAT</text><rect x="25" y="52" width="210" height="110" rx="10" fill="#f1f5f9" stroke="#64748b"/><text x="130" y="76" text-anchor="middle" font-size="13" font-weight="bold" fill="#334155">Vefat Haberi</text><text x="130" y="94" text-anchor="middle" font-size="11" fill="#475569">(632, Medine)</text><text x="130" y="118" text-anchor="middle" font-size="11" fill="#334155">Sahabiler sarsıldı;</text><text x="130" y="135" text-anchor="middle" font-size="11" fill="#334155">Hz. Ömer kabullenemedi.</text><line x1="237" y1="107" x2="265" y2="107" stroke="#64748b" stroke-width="2"/><polygon points="265,101 275,107 265,113" fill="#64748b"/><rect x="275" y="52" width="210" height="110" rx="10" fill="#fefce8" stroke="#eab308"/><text x="380" y="76" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Hz. Ebu Bekir\'in Sözü</text><text x="380" y="100" text-anchor="middle" font-size="11" fill="#334155">"Kim Allah\'a ibadet ediyorsa</text><text x="380" y="117" text-anchor="middle" font-size="11" fill="#334155">bilsin ki Allah diridir, ölmez."</text><text x="380" y="141" text-anchor="middle" font-size="11" font-weight="bold" fill="#854d0e">Âl-i İmrân, 144</text><line x1="487" y1="107" x2="515" y2="107" stroke="#64748b" stroke-width="2"/><polygon points="515,101 525,107 515,113" fill="#64748b"/><rect x="525" y="52" width="210" height="110" rx="10" fill="#f0fdf4" stroke="#22c55e"/><text x="630" y="76" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Sonuç</text><text x="630" y="100" text-anchor="middle" font-size="11" fill="#334155">Bağlılık; Allah\'ın mesajına,</text><text x="630" y="117" text-anchor="middle" font-size="11" fill="#334155">Kur\'an\'a ve sünnete</text><text x="630" y="134" text-anchor="middle" font-size="11" fill="#334155">bağlılıkla sürer.</text><rect x="25" y="185" width="345" height="115" rx="10" fill="#eff6ff" stroke="#3b82f6"/><text x="197" y="209" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Hz. Ömer ve Hacerülesved</text><text x="197" y="234" text-anchor="middle" font-size="11" fill="#334155">"Fayda da zarar da veremeyen bir taşsın.</text><text x="197" y="251" text-anchor="middle" font-size="11" fill="#334155">Resulullah\'ın seni öptüğünü görmeseydim</text><text x="197" y="268" text-anchor="middle" font-size="11" fill="#334155">seni öpmezdim." (Buhârî)</text><text x="197" y="289" text-anchor="middle" font-size="10" font-weight="bold" fill="#1e3a8a">Tevhit korunur, ibadette ölçü sünnettir.</text><rect x="390" y="185" width="345" height="115" rx="10" fill="#fff7ed" stroke="#f97316"/><text x="562" y="209" text-anchor="middle" font-size="13" font-weight="bold" fill="#c2410c">Hz. Ebu Bekir\'in Kararlılığı</text><text x="562" y="234" text-anchor="middle" font-size="11" fill="#334155">"Resulullah\'ın yapmakta olduğu</text><text x="562" y="251" text-anchor="middle" font-size="11" fill="#334155">hiçbir şeyi terk etmem." (Buhârî)</text><text x="562" y="275" text-anchor="middle" font-size="10" font-weight="bold" fill="#9a3412">Sevgi, sünneti yaşatmakla kalıcı olur.</text></svg>', 'b6': '<svg viewBox="0 0 760 330" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif"><rect width="760" height="330" fill="#f8fafc" rx="14"/><text x="380" y="32" text-anchor="middle" font-size="16" font-weight="bold" fill="#1e293b">MUHACİRLERDEN BUGÜNE: BAĞLILIĞI DÖNÜŞTÜRMEK</text><rect x="25" y="50" width="340" height="34" rx="8" fill="#1e40af"/><text x="195" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#ffffff">Muhacirin Davranışı</text><rect x="395" y="50" width="340" height="34" rx="8" fill="#15803d"/><text x="565" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#ffffff">Benim Hayatımdaki Karşılığı</text><rect x="25" y="92" width="340" height="40" rx="8" fill="#eff6ff" stroke="#93c5fd"/><text x="38" y="117" font-size="11" fill="#334155">Hz. Ali emanetleri sahiplerine teslim etti.</text><rect x="395" y="92" width="340" height="40" rx="8" fill="#f0fdf4" stroke="#86efac"/><text x="408" y="117" font-size="11" fill="#334155">Ödünç aldığımı zamanında, sağlam iade ederim.</text><rect x="25" y="140" width="340" height="40" rx="8" fill="#eff6ff" stroke="#93c5fd"/><text x="38" y="165" font-size="11" fill="#334155">Hz. Esma müşriklere sır vermedi.</text><rect x="395" y="140" width="340" height="40" rx="8" fill="#f0fdf4" stroke="#86efac"/><text x="408" y="165" font-size="11" fill="#334155">Arkadaşımın bana açtığı sırrı saklarım.</text><rect x="25" y="188" width="340" height="40" rx="8" fill="#eff6ff" stroke="#93c5fd"/><text x="38" y="213" font-size="11" fill="#334155">İbn Mes\'ud Kur\'an\'ı öğrenip okudu.</text><rect x="395" y="188" width="340" height="40" rx="8" fill="#f0fdf4" stroke="#86efac"/><text x="408" y="213" font-size="11" fill="#334155">Her gün birkaç ayeti anlamıyla okurum.</text><rect x="25" y="236" width="340" height="40" rx="8" fill="#eff6ff" stroke="#93c5fd"/><text x="38" y="261" font-size="11" fill="#334155">Ümmü Seleme sabretti, görüşünü söyledi.</text><rect x="395" y="236" width="340" height="40" rx="8" fill="#f0fdf4" stroke="#86efac"/><text x="408" y="261" font-size="11" fill="#334155">Zorlukta sabreder, fikrimi edeple söylerim.</text><rect x="25" y="284" width="340" height="36" rx="8" fill="#eff6ff" stroke="#93c5fd"/><text x="38" y="307" font-size="11" fill="#334155">Hz. Ömer sünnete titizlikle uydu.</text><rect x="395" y="284" width="340" height="36" rx="8" fill="#f0fdf4" stroke="#86efac"/><text x="408" y="307" font-size="11" fill="#334155">Selam, güler yüz ve temizliği yaşarım.</text><polygon points="372,106 388,112 372,118" fill="#64748b"/><polygon points="372,154 388,160 372,166" fill="#64748b"/><polygon points="372,202 388,208 372,214" fill="#64748b"/><polygon points="372,250 388,256 372,262" fill="#64748b"/><polygon points="372,296 388,302 372,308" fill="#64748b"/></svg>'}

def uygula(v):
    for idx, b in enumerate(v.get('bolumler', []), 1):
        svg = GORSELLER.get(f'b{idx}') or GORSELLER.get(str(idx))
        if svg:
            b['gorsel'] = svg
    return v
